"""Write the current plan (from the task portal's data.js) into this repo's README.

Replaces everything between <!-- PLAN:START --> and <!-- PLAN:END --> with a table per phase:
task (linked to its folder), people (owner first), head-count, start, deadline and status.
The portal stays the only place where the plan is edited; this copy is regenerated by the
"Task board sync" workflow. Only writes README.md when the plan itself changed (the "last
synced" time alone does not count), so it never makes empty commits.

Env: PORTAL_FILE (portal data.js), README (default README.md), PORTAL_URL (link shown in the text).
"""
import datetime as dt
import json
import os
import re
import sys

START, END = '<!-- PLAN:START -->', '<!-- PLAN:END -->'
STAMP_RE = re.compile(r'^_Synced from .*$', re.M)


def now_cairo():
    try:
        from zoneinfo import ZoneInfo
        return dt.datetime.now(ZoneInfo('Africa/Cairo'))
    except Exception:
        return dt.datetime.now(dt.timezone.utc)


def slug(s):
    """Same folder naming as the portal (app.js slug())."""
    full = re.sub(r'^-+|-+$', '', re.sub(r'[^a-z0-9]+', '-', (s or '').lower().replace('&', 'and')))
    if len(full) <= 40:
        return full
    cut = re.sub(r'-[^-]*$', '', full[:41])
    while re.search(r'-(the|and|of|for|a|an|to|with)$', cut):
        cut = re.sub(r'-[^-]*$', '', cut)
    return cut


def fmt(iso):
    d = dt.date.fromisoformat(iso)
    return d.strftime('%a %b ') + str(d.day)


def build(data, today, portal_url, repo_root):
    groups = data['groups']
    members = {m['id']: (m.get('name') or m.get('label') or m['id']) for m in data['members']}
    tasks_by_group = {g['id']: [t for t in data['tasks'] if t['group'] == g['id']] for g in groups}

    def code_key(t):
        return [int(x) if x.isdigit() else x for x in str(t['code']).split('.')]

    def done(g):
        ts = tasks_by_group[g['id']]
        return bool(ts) and all(t['status'] == 'done' for t in ts)

    def locked_by(g):
        if not g.get('gated'):
            return None
        same = [x for x in groups if x['category'] == g['category']]
        i = same.index(g)
        if i == 0:
            return None
        prev = same[i - 1]
        return None if (done(prev) and not locked_by(prev)) else prev

    def short(g):
        return (g.get('short') or g['id']).split('·')[0].strip()

    def folder(t, g):
        if t.get('folder'):
            return t['folder']
        code = str(t['code']).zfill(2) if str(t['code']).isdigit() else str(t['code'])
        return f"{g.get('folder', g['id'])}/{code}_{slug(t['title'])}"

    out = ['## 📋 Current plan', '',
           f"_Synced from the [task portal]({portal_url}) · {now_cairo().strftime('%a %b %d, %H:%M')} (Cairo time). "
           "Dates and people are edited on the portal, not here._", '']
    for g in groups:
        ts = sorted(tasks_by_group[g['id']], key=code_key)
        if done(g):
            state = '✅ Complete'
        elif locked_by(g):
            state = f'🔒 Starts when {short(locked_by(g))} is 100% done'
        else:
            state = '▶ Active'
        span = f" · {fmt(min(t['start'] for t in ts))} → {fmt(max(t['due'] for t in ts))}" if ts else ''
        out += [f"### {g.get('short') or g['id']} — {state}{span}", '']
        if not ts:
            out += ['_Tasks will be added later._', '']
            continue
        out += ['| Task | People (owner first) | Needed | Start | Deadline | Status |', '|---|---|---|---|---|---|']
        for t in ts:
            path = folder(t, g)
            link = path + '/' if os.path.isdir(os.path.join(repo_root, *path.split('/'))) else None
            name = f"Task {t['code']}: {t['title']}"
            task_cell = f'[{name}]({link})' if link else name
            people = ', '.join(('**' + members.get(a, a) + '**') if i == 0 else members.get(a, a)
                               for i, a in enumerate(t.get('assignees') or [])) or '_not assigned_'
            needed = str(t['needed']) if t.get('needed') else '—'
            if t['status'] == 'done':
                status = '✅ Done' + (f" ([work]({t['docLink']}))" if (t.get('docLink') or '').startswith('https://') else '')
            elif locked_by(g):
                status = '🔒 Waiting'
            elif t['due'] < today:
                status = ('🟦 In Progress' if t['status'] == 'doing' else '⬜ To Do') + ' · ⚠️ overdue'
            else:
                status = '🟦 In Progress' if t['status'] == 'doing' else '⬜ To Do'
            out.append(f"| {task_cell} | {people} | {needed} | {fmt(t['start'])} | **{fmt(t['due'])}** | {status} |")
        out.append('')
    return '\n'.join(out).rstrip() + '\n'


def main():
    if hasattr(sys.stdout, 'reconfigure'):
        sys.stdout.reconfigure(encoding='utf-8')
    portal = os.environ.get('PORTAL_FILE', 'portal/data.js')
    readme = os.environ.get('README', 'README.md')
    url = os.environ.get('PORTAL_URL', 'https://salehnassar.github.io/agv-task-portal/')
    src = open(portal, encoding='utf-8').read()
    data = json.loads(src[src.index('{'):src.rindex('}') + 1])
    text = open(readme, encoding='utf-8').read()
    if START not in text or END not in text:
        print(f'{readme} has no {START} … {END} block; nothing to do.')
        return 0
    block = build(data, now_cairo().date().isoformat(), url, os.path.dirname(os.path.abspath(readme)))
    a, b = text.index(START) + len(START), text.index(END)
    old = text[a:b]
    if STAMP_RE.sub('', old).strip() == STAMP_RE.sub('', block).strip():
        print('Plan unchanged; README left as is.')
        return 0
    open(readme, 'w', encoding='utf-8', newline='\n').write(text[:a] + '\n' + block + text[b:])
    print('README plan updated.')
    return 0


if __name__ == '__main__':
    sys.exit(main())
